-- 기회비용·매몰비용 레슨: 쉽게 설명 -> 특징 -> 경제학적 비용 표 -> 복합 예시 표. type quiz는 카드에 안 보이고 퀴즈에서만 나온다.
-- 기존 visuals는 뒤에 그대로 둔다. '기회비용 쉽게 설명'/'매몰비용 쉽게 설명'이 이미 있으면 건너뜀(다시 실행해도 중복 없음).

-- 기회비용
UPDATE public.words SET visuals = '[
  {"type":"text","title":"기회비용 쉽게 설명","body":"하나를 고르면 나머지는 포기해야 해요. 포기한 것들 중 가장 값진 하나가 기회비용이에요.\n5천 원으로 짜장면과 짬뽕 중 짜장면을 골랐다면, 못 먹은 짬뽕이 기회비용이에요.\n가게 주인이 같은 밀가루로 호빵 대신 호떡을 만들기로 했다면, 못 만든 호빵이 기회비용이고요."},
  {"type":"text","title":"꼭 알아둘 특징","body":"자원이 부족해서(희소성) 생겨요. 공기처럼 넘치는 것에는 기회비용이 없어요.\n기회비용이 작은 선택일수록 좋은 선택이에요.\n그래서 기회비용은 무엇을 고를지 정하는 기준이 돼요."},
  {"type":"table","title":"회사를 그만두고 1년 고시 공부를 하면","columns":["비용","내용","금액"],"rows":[["회계학적 비용(명시적)","실제로 낸 수강료·교재비","1,000만 원"],["암묵적 비용","공부하느라 못 받은 연봉","2,000만 원"],["경제학적 비용(=기회비용)","둘을 더한 값","3,000만 원"]],"caption":"낸 돈 1,000만 원만 보면 싸 보이지만, 실제로 포기한 가치는 3,000만 원이에요."},
  {"type":"table","title":"연봉 5,000만 원 회사원이 식당을 차린다면(1년)","columns":["비용","내용","금액"],"rows":[["암묵적 비용","포기한 연봉","5,000만 원"],["암묵적 비용","가게 자금 1억 원의 예금 이자(2%)","200만 원"],["암묵적 비용","내 상가를 세놓았으면 받았을 월세(100만 원 × 12)","1,200만 원"],["회계학적 비용","예상 운영비","3,600만 원"],["기회비용 합계","","1억 원"],["빼야 할 것","이미 낸 컨설팅비(매몰비용)","500만 원 - 계산에서 제외"]],"caption":"예상 매출이 1억 원보다 많아야 개업이 합리적이에요."},
  {"type":"quiz","q":"기회비용에 대한 설명으로 옳은 것은?","options":["기회비용은 클수록 좋다","자원이 풍부할 때 생긴다","선택하느라 포기한 것 중 가장 값진 것이다","의사결정과는 관계없다"],"answer":2},
  {"type":"quiz","q":"경제학적 비용에 대한 설명으로 옳은 것은?","options":["실제로 낸 회계학적 비용만 뜻한다","암묵적 비용은 넣지 않는다","회계학적 비용과 암묵적 비용을 더한 것이다","항상 회계학적 비용보다 작다"],"answer":2},
  {"type":"quiz","q":"민아는 연봉 1,000만 원을 포기하고, 세놓으면 1,000만 원을 받을 상가에서 제과점을 열려 해요. 운영비 1,500만 원, 예상 수입 4,000만 원일 때 옳지 않은 것은?","options":["회계학적 비용은 1,500만 원","포기한 연봉 1,000만 원은 암묵적 비용","포기한 임대료 1,000만 원은 암묵적 비용","개업하면 경제적 이익은 2,500만 원"],"answer":3}
]'::jsonb || COALESCE(visuals,'[]'::jsonb)
WHERE word = '기회비용' AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"title":"기회비용 쉽게 설명"}]';

-- 매몰비용
UPDATE public.words SET visuals = '[
  {"type":"text","title":"매몰비용 쉽게 설명","body":"이미 써 버려서 다시 돌려받을 수 없는 돈이나 시간이에요.\n어떤 선택을 하든 돌아오지 않으니, 앞으로의 결정에는 넣지 말아야 해요.\n\"본전 생각\"이 바로 매몰비용에 끌려가는 마음이에요."},
  {"type":"text","title":"다시 팔 수 있다면?","body":"산 물건을 다시 팔아 돈을 되찾을 수 있다면, 그 돈은 회수할 수 있으니 매몰비용이 아니에요.\n되찾을 수 없는 부분만 매몰비용이에요."},
  {"type":"text","title":"재미없는 공연, 끝까지 볼까?","body":"표값은 이미 냈고, 남아도 나가도 돌아오지 않아요.\n그러니 표값은 빼고 남은 시간을 어디에 쓰는 게 나은지만 비교해요.\n표값이 아까워 끝까지 앉아 있으면 돈에 이어 시간까지 잃어요."},
  {"type":"quiz","q":"매몰비용에 대한 설명으로 옳은 것은?","options":["의사결정에 반드시 넣어야 한다","다시 팔 수 있는 물건에 쓴 돈도 매몰비용이다","이미 써서 되찾을 수 없는 비용이다","앞으로의 이익을 늘리는 데 쓸 수 있다"],"answer":2}
]'::jsonb || COALESCE(visuals,'[]'::jsonb)
WHERE word = '매몰비용' AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"title":"매몰비용 쉽게 설명"}]';

-- 확인: 두 줄, 기회비용 n 7 이상 / 매몰비용 n 4 이상
SELECT id, word, jsonb_array_length(visuals) AS n FROM public.words WHERE word IN ('기회비용','매몰비용');
